import { createSlice, createAsyncThunk, createSelector } from "@reduxjs/toolkit";
import axios from "axios";

const API_URL = "http://127.0.0.1:8000/api/users/";

// --- Thunks ---

export const fetchUsersAsync = createAsyncThunk(
  "users/fetchAll",
  async (_, { rejectWithValue }) => {
    const token = localStorage.getItem("token");
    try {
      const res = await axios.get(API_URL, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return res.data.map(user => ({
        ...user,
        profile: user.profile || { bio: "", phone: "" },
      }));
    } catch (err) {
      return rejectWithValue(err.response?.data || err.message);
    }
  }
);

export const updateUserAsync = createAsyncThunk(
  "users/update",
  async (user, { rejectWithValue }) => {
    const token = localStorage.getItem("token");

    const payload = {
      username: user.username,
      email: user.email,
      first_name: user.first_name,
      last_name: user.last_name,
      is_active: user.is_active,
      profile: {
        bio: user.profile?.bio || "",
        phone: user.profile?.phone || "",
      },
    };

    if (!user.id) {
      return rejectWithValue("User ID is required for update");
    }

    try {
      const res = await axios.patch(`${API_URL}${user.id}/`, payload, {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
      });
      // Ensure the returned object always has profile
      return { ...res.data, profile: res.data.profile || { bio: "", phone: "" } };
    } catch (err) {
      return rejectWithValue(err.response?.data || err.message);
    }
  }
);

export const deleteUserAsync = createAsyncThunk(
  "users/delete",
  async (id, { rejectWithValue }) => {
    const token = localStorage.getItem("token");
    if (!id) return rejectWithValue("User ID is required for deletion");
    try {
      await axios.delete(`${API_URL}${id}/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return id;
    } catch (err) {
      return rejectWithValue(err.response?.data || err.message);
    }
  }
);

// --- Slice ---

const initialState = {
  users: [],
  searchTerm: "",
  loading: false,
  error: null,
};

const usersSlice = createSlice({
  name: "users",
  initialState,
  reducers: {
    setSearchTerm(state, action) {
      state.searchTerm = action.payload;
    },
    updateUserLocally(state, action) {
      const updated = action.payload;
      const index = state.users.findIndex(u => u.id === updated.id);
      if (index !== -1) state.users[index] = updated;
    },
  },
  extraReducers: builder => {
    builder
      .addCase(fetchUsersAsync.pending, state => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchUsersAsync.fulfilled, (state, action) => {
        state.loading = false;
        state.users = action.payload;
      })
      .addCase(fetchUsersAsync.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || "Failed to fetch users";
      })
      .addCase(updateUserAsync.fulfilled, (state, action) => {
        const updated = action.payload;
        const index = state.users.findIndex(u => u.id === updated.id);
        if (index !== -1) state.users[index] = updated;
      })
      .addCase(updateUserAsync.rejected, (state, action) => {
        state.error = action.payload || "Update failed";
      })
      .addCase(deleteUserAsync.fulfilled, (state, action) => {
        state.users = state.users.filter(u => u.id !== action.payload);
      })
      .addCase(deleteUserAsync.rejected, (state, action) => {
        state.error = action.payload || "Delete failed";
      });
  },
});

export const selectUsersState = state => state.users;

export const selectFilteredUsers = createSelector(
  [selectUsersState],
  s =>
    s.users.filter(u =>
      (u.username || "").toLowerCase().includes((s.searchTerm || "").toLowerCase())
    )
);

export const { setSearchTerm, updateUserLocally } = usersSlice.actions;

export default usersSlice.reducer;
